from collections import deque,Counter
D4=np.array([[1,0,1,0,7,0,0],[1,1,9,1,0,1,0],[0,0,1,1,0,2,0],[0,0,0,0,3,0,1],[0,4,0,1,0,0,1],[0,0,1,0,2,0,8],[0,0,1,0,7,3,1]])
def comps(D):
 seen=set(); out=[]
 for r in range(7):
  for c in range(7):
   v=D[r,c]
   if v==0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for a,b in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
     if 0<=a<7 and 0<=b<7 and D[a,b]==v and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   out.append((v,len(comp),(min(x for x,y in comp),min(y for x,y in comp),max(x for x,y in comp),max(y for x,y in comp)),comp))
 return out
for D in [D1,D2,D3,D4]:
 print(Counter(D.flatten()))
 print(sorted([(v,n,b) for v,n,b,_ in comps(D)],key=lambda x:-x[1])[:10])

