def near_patterns(D, outmask):
 arr=[]
 for r in range(5):
  for c in range(5):
   b=D[r:r+3,c:c+3]
   for name,mask in [('zero',b==0),('nonzero',b!=0),('one',b==1),('otherthan1',b!=1)]:
    dist=np.count_nonzero(mask!=outmask)
    if dist<=2:arr.append((dist,r,c,name,b.tolist()))
 return sorted(arr)
