def find_oriented(D,O):
 m=np.zeros((3,3),bool)
 for r,c in O:m[r,c]=1
 arr=[]
 forms=[]
 for k in range(4):
  t=np.rot90(m,k)
  forms.append(t)
  forms.append(np.fliplr(t))
 for r in range(5):
  for c in range(5):
   b=D[r:r+3,c:c+3]
   vals=list(set(D.flatten()))
   for masknum in range(1,1<<len(vals)):
    ss=[vals[i] for i in range(len(vals)) if masknum>>i&1]
    mm=np.isin(b,ss)
    if any(np.array_equal(mm,f) for f in forms): arr.append((r,c,ss))
 return arr
